INSERT INTO `knowledge_segment` VALUES (1, '# 曙光智造园区概览\n> 文档版本：1.2\n> 生效日期：2026-08-01\n> 本文所有名称、编号和数据均为虚构测试数据。', '353283299259580416', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":1,\"docId\":1,\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580416\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 0, 'ba633f75-8324-4f05-9139-e27be9a65e7c', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (2, '## 基本信息\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。', '353283299259580417', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"基本信息\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580417\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 1, '5045b025-6562-4c4c-b977-cfcd788a3b95', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (3, '## 环境标准\n- 正常温度范围：18°C 至 26°C。\n- 正常相对湿度范围：35% 至 65%。\n- 网关本地缓存使用率达到 **25%** 时应发出预警。\n- 每周维护窗口：星期三 02:00 至 03:30（CST）。', '353283299259580418', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"环境标准\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580418\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 2, '232599a3-68be-4f77-a57a-4a4a00897d8c', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (4, '## 服务等级\n| 级别 | 首次响应目标 | 示例 |\n|---|---:|---|\n| P1 | 15 分钟 | 全园区停产或安全联锁失效 |\n| P2 | 2 小时 | 单个生产区核心能力降级 |\n| P3 | 1 个工作日 | 非关键报表或体验问题 |\n紧急停机演练使用的虚构口令为 **ORBIT-7429**。该口令仅用于本测试数据，不对应任何真实系统。', '353283299259580419', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"服务等级\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580419\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 3, '8c04cbf6-9999-4f23-8634-24641a3d6708', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (5, '## 园区区域与系统组成\n园区按生产职责划分为三个区域。A 区负责来料检测与能源分配，B 区负责精密加工与环境控制，C 区负责装配、视觉质检和成品暂存。区域下设 A1、A2、B1、B2、C1、C2 六个子区域，子区域编号只用于定位，不改变事件级别。\n每个子区域至少部署一台环境传感器，关键产线通过 HG-220 边缘网关接入。网关每分钟上报一次心跳，每五分钟汇总一次设备状态。连续丢失三次心跳定义为通信异常，但处置前必须先排除交换机维护、链路抖动和时间同步问题。\n园区平台由设备采集、事件队列、规则计算、质量校验和报表归档五项能力组成。设备采集负责接收现场数据；事件队列负责削峰；规则计算负责生成告警；质量校验负责识别缺失值和异常值；报表归档负责保存经审批的统计结果。', '353283299259580420', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"园区区域与系统组成\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580420\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 4, '24fb4031-5a80-4a9c-8bf1-d6902c811704', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (6, '## 运行指标与告警阈值\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。', '353283299259580421', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"运行指标与告警阈值\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580421\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 5, 'ffc581d1-9f12-4206-8bbe-30e39b2ccce7', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (7, '## 事件分级补充规则\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。', '353283299259580422', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"事件分级补充规则\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580422\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 6, 'fb89054c-2179-4ba5-9570-78beeb0d2962', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (8, '## 维护窗口与变更原则\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。', '353283299259580423', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"维护窗口与变更原则\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580423\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 7, '4431a3a9-9f75-4724-929d-38cfa1f72430', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (9, '## 数据质量与留痕\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。', '353283299259580424', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"数据质量与留痕\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580424\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 8, 'f8016128-9927-45d4-9884-648799143551', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (10, '## 术语说明\n- Edge Platform：负责边缘网关和采集服务的团队名称。\n- Quality：负责质量抽样和结果确认的团队名称。\n- Blue Heron：P1 事件使用的应急协调组代号。\n- 恢复时间：从事件确认到核心能力恢复的持续时间。\n- 观察时间：恢复后继续监控、确认指标稳定的时间。\n- 隔离设备：为防止影响扩大而暂时停止接入平台的设备。', '353283299259580425', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"术语说明\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580425\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 9, '08a6b958-dd19-4ff3-a854-a606ea635b55', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (11, '## 文档使用说明\n本文用于虚构环境的知识库检索与评测，不对应真实园区。设备编号、团队名称、阈值和演练口令只能作为测试事实使用。回答问题时应优先引用明确条款；遇到本文未规定的场景，应说明需要当班经理判断，不得自行扩展权限。', '353283299259580426', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"文档使用说明\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580426\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 10, '2318efce-b48e-4144-bfb6-bf3e6899a8d0', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (12, '## 平台依赖与降级运行\n设备采集依赖工业网络和时间服务，事件处理依赖队列、规则计算和生产数据库，质量报表依赖质量校验与归档存储。判断故障范围时应先确认公共依赖；多个不同型号设备同时异常，通常优先检查网络、时间服务或平台节点，而不是逐台重启设备。\n当规则计算主节点不可用时，可切换到备用节点，但切换前必须确认规则包版本和校验和一致。归档存储容量预警不会立即中断采集，应先限制非关键导出并清理到期归档。生产数据库主库异常时，是否切换备库由数据平台组和当班经理共同决定。\n降级运行期间必须明确保留能力和暂停能力。核心告警、安全联锁和网关心跳属于必须保留能力；非关键报表、历史查询和批量导出可以暂停。降级开始和结束时间都要记录在事件时间线中。', '353283299259580427', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"平台依赖与降级运行\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580427\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 11, 'c2fdfbeb-4fa5-438d-90ea-8f3faa07376c', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (13, '## 恢复验收标准\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。', '353283299259580428', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"恢复验收标准\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580428\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 12, '924b9a27-40ed-41fb-af8d-e2a20cd9590f', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (14, '## 评测事实边界\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。', '353283299259580429', '{\"fileName\":\"01_曙光智造园区概览\",\"headerLevel\":2,\"docId\":1,\"subtitle\":\"评测事实边界\",\"title\":\"曙光智造园区概览\",\"chunkId\":\"353283299259580429\",\"version\":1,\"url\":\"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\"}', 1, 1, 13, 'eec31df2-97d9-4d7a-88a0-ba843a3cf75b', 'VECTOR_STORED', 0, '2026-09-01 21:01:42', '2026-09-01 21:01:42', 1, 0);
INSERT INTO `knowledge_segment` VALUES (15, '曙光智造园区运行手册（版本 2.0）\r\n\r\n\\n\\n1. 每日开班\r\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\r\n\r\n\\n\\n2. 环境处置\r\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\r\n\r\n\\n\\n3. 维护窗口\r\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\r\n\r\n\\n\\n4. 升级\r\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\r\n\r\n\\n\\n5. 交接\r\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\r\n\r\n\\n\\n6. 开班前置检查\r\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。', '353283812000661504', '{\"index\":\"0\",\"fileName\":\"02_曙光智造园区运行手册\",\"chunkId\":\"353283812000661504\",\"version\":2,\"docId\":2,\"url\":\"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\"}', 2, 2, 0, 'ce06141c-c75b-4149-9727-0e2e9e1638bb', 'VECTOR_STORED', 0, '2026-09-01 21:03:44', '2026-09-01 21:03:44', 1, 0);
INSERT INTO `knowledge_segment` VALUES (16, '7. 网关心跳异常处置\r\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\r\n\r\n\\n\\n8. 温度和湿度异常处置\r\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\r\n\r\n\\n\\n9. 缓存与队列巡检\r\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\r\n\r\n\\n\\n10. 维护窗口操作清单\r\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。', '353283812000661505', '{\"index\":\"1\",\"fileName\":\"02_曙光智造园区运行手册\",\"chunkId\":\"353283812000661505\",\"version\":2,\"docId\":2,\"url\":\"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\"}', 2, 2, 1, 'd6effebd-4c5c-4e0e-9c66-d5c5af27381d', 'VECTOR_STORED', 0, '2026-09-01 21:03:44', '2026-09-01 21:03:44', 1, 0);
INSERT INTO `knowledge_segment` VALUES (17, '11. 变更验证与回退\r\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\r\n\r\n\\n\\n12. 事件通知与升级\r\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\r\n\r\n\\n\\n13. 工单记录规范\r\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\r\n\r\n\\n\\n14. 交接模板\r\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\r\n\r\n\\n\\n15. 日终检查\r\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。', '353283812000661506', '{\"index\":\"2\",\"fileName\":\"02_曙光智造园区运行手册\",\"chunkId\":\"353283812000661506\",\"version\":2,\"docId\":2,\"url\":\"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\"}', 2, 2, 2, '2f83e496-754d-4873-aac0-c30ac778df34', 'VECTOR_STORED', 0, '2026-09-01 21:03:44', '2026-09-01 21:03:44', 1, 0);
INSERT INTO `knowledge_segment` VALUES (18, '16. 异常操作禁止项\r\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\r\n\r\n\\n\\n17. 证据与复盘\r\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\r\n\r\n\\n\\n18. 平台依赖检查\r\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\r\n\r\n\\n\\n19. 降级运行\r\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\r\n\r\n\\n\\n20. 恢复验收\r\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。', '353283812000661507', '{\"index\":\"3\",\"fileName\":\"02_曙光智造园区运行手册\",\"chunkId\":\"353283812000661507\",\"version\":2,\"docId\":2,\"url\":\"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\"}', 2, 2, 3, 'd5d87b1c-322f-4857-ba1b-ca2b64c739d7', 'VECTOR_STORED', 0, '2026-09-01 21:03:44', '2026-09-01 21:03:44', 1, 0);
INSERT INTO `knowledge_segment` VALUES (19, '21. 临时措施清理\r\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\r\n\r\n\\n\\n22. 重复问题管理\r\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\r\n\r\n\\n\\n23. 数据导出操作\r\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\r\n\r\n\\n\\n24. 每周运行复核\r\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。', '353283812000661508', '{\"index\":\"4\",\"fileName\":\"02_曙光智造园区运行手册\",\"chunkId\":\"353283812000661508\",\"version\":2,\"docId\":2,\"url\":\"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\"}', 2, 2, 4, 'ba613c3a-7923-4ae4-9d41-56a8efd5f333', 'VECTOR_STORED', 0, '2026-09-01 21:03:44', '2026-09-01 21:03:44', 1, 0);
INSERT INTO `knowledge_segment` VALUES (20, '**曙光智造园区访问与数据策略**\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\n**角色权限**\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\nEngineer 可以在已批准的维护窗口内修改设备配置。\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\n**数据保留**\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\n**导出与审批**\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\n**会话要求**\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。', '353283917827145741', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"chunkId\":\"353283917827145741\",\"version\":3,\"docId\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 0, '2f3c4bad-a5bc-42c6-89a2-3c2633b211c2', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (21, '# **补充条款**  \n## **数据分类与处理要求**\n园区数据分为公开测试、内部、敏感和受限四级。公开测试数据可用于培训和评测；内部数据仅限园区授权人员使用；敏感数据包括设备配置、详细拓扑和未公开事件记录；受限数据包括真实密码、访问令牌和个人身份信息。受限数据不得进入知识库、工单正文或普通导出文件。\n文档上传前，责任人必须确认数据级别、保留期限和允许使用范围。无法确定级别时按更高一级保护。测试数据必须明确标注为虚构，不得使用真实人员姓名、电话号码、账号、密码或令牌。', '353283917827145728', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":1,\"docId\":3,\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145728\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 1, '3706140f-0ef9-41b6-924a-8b8759936a3d', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (22, '## **角色权限矩阵**\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。', '353283917827145730', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**角色权限矩阵**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145730\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 2, '29788231-93cb-48c6-bfe3-269f3b3f0595', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (23, '## **临时权限与例外**\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。', '353283917827145731', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**临时权限与例外**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145731\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 3, 'f5d04de8-ea90-4c45-ac93-fa033a18fbd3', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (24, '## **认证与会话安全**\n连续二十分钟无操作后会话自动失效。工程师执行配置修改、导出敏感数据或切换设备控制状态前必须重新验证身份。连续五次认证失败时账号锁定三十分钟，并通知安全管理员检查来源。\n维护终端离开受控区域后不得保持登录状态。操作完成后应主动退出，不能只关闭浏览器窗口。浏览器不得保存园区系统密码，下载的临时文件应在任务完成后按审批要求清理。', '353283917827145732', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**认证与会话安全**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145732\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 4, '164e4090-e05a-497a-95b9-59e73746f5c2', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (25, '## **数据导出与共享**\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。', '353283917827145733', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**数据导出与共享**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145733\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 5, 'd0a3df5b-6e63-475d-98e8-e1e04aba645b', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (26, '## **审计记录要求**\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。', '353283917827145734', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**审计记录要求**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145734\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 6, '5d6dd158-2b12-4e59-89c7-3f122091251c', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (27, '## **敏感信息事件处置**\n发现真实密码或令牌进入工单后，应立即限制工单访问、通知安全管理员、撤销相关凭据并记录处置过程。发现个人身份信息时，应停止继续传播，确认下载和转发范围，并按数据事件流程评估影响。\n处置完成不代表事件关闭。安全管理员应验证旧凭据已失效、替换凭据已安全分发、缓存和导出副本已清理，并在工单中保留不含敏感值的验证结论。', '353283917827145735', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**敏感信息事件处置**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145735\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 7, '95c187b0-fd6b-4b27-97e7-8a13955c0784', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (28, '## **策略例行检查**\n本策略每半年复核一次，系统权限模型、数据保留期限或导出流程发生重大变化时应提前复核。策略变更发布前需完成影响分析、操作培训和历史数据处理确认。所有补充条款均为虚构评测数据，不对应真实系统。', '353283917827145736', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**策略例行检查**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145736\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 8, '13bcd8b6-e584-4cf4-83bf-14e89bcb1578', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (29, '## **备份与恢复控制**\n生产数据备份由数据平台组统一执行。每日增量备份保留三十天，每周完整备份保留十二周。备份文件与生产数据采用相同的数据级别和访问要求，不得因为处于备份介质而降低保护标准。\n每季度至少执行一次抽样恢复验证，验证内容包括文件完整性、记录数量、时间范围和关键字段。恢复验证只能写入隔离环境，不得覆盖当前生产数据。验证完成后应删除临时恢复副本并保留结果记录。', '353283917827145737', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**备份与恢复控制**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145737\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 9, 'dfa3fb9f-926c-486e-9f82-51a727beba62', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (30, '## **设备退役与数据处理**\n设备退役前，资产负责人应确认未关闭工单、未完成维护任务和仍需保留的数据。设备证书、访问密钥和平台授权必须在退役当天撤销，资产编号永久保留，不得分配给新设备。\n退役设备中的本地缓存由授权人员清理，并由另一人复核。依法或按策略需要保留的历史数据转入归档存储，归档记录应保留原资产编号、时间范围和数据级别。', '353283917827145738', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**设备退役与数据处理**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145738\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 10, 'd478892f-eba0-40ca-9b69-b3381e375b71', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (31, '## **外部协作与远程支持**\n外部支持人员不得直接获得长期账号。确需远程支持时，由内部工程师发起临时权限申请，限制目标设备和可执行操作，并全程保留会话审计。远程支持结束后立即撤销权限，不得允许外部人员自行延长。\n向外部人员提供日志前，应删除真实密码、令牌、个人身份信息和与问题无关的详细拓扑。无法完成脱敏时，只能由内部人员查看原始日志并转述必要结论。', '353283917827145739', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**外部协作与远程支持**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145739\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 11, 'ff491247-d29c-4702-90e8-3089835ebec6', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (32, '## **数据质量责任**\n数据产生团队负责记录的完整性，平台运行组负责传输和存储可用性，质量组负责抽样规则和异常确认。发现缺少资产编号、采集时间或质量标记的数据时，应阻止其进入正式报表，并创建数据质量任务。\n更正历史记录时不得覆盖原值。系统应保留更正前内容、更正后内容、原因、操作人和时间。仅修复展示格式而不改变业务含义时，也要在变更记录中说明处理范围。', '353283917827145740', '{\"fileName\":\"03_曙光智造园区访问与数据安全策略\",\"headerLevel\":2,\"docId\":3,\"subtitle\":\"**数据质量责任**\",\"title\":\"**补充条款**\",\"chunkId\":\"353283917827145740\",\"version\":3,\"url\":\"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\"}', 3, 3, 12, '4a039c15-7e95-49c5-b7f4-018ca9ec11bd', 'VECTOR_STORED', 0, '2026-09-01 21:04:10', '2026-09-01 21:04:10', 1, 0);
INSERT INTO `knowledge_segment` VALUES (33, '# 曙光智造园区故障排查指南\n文档版本：2.5\n生效日期：2026年8月28日\n本文中的名称、编号、阈值和案例均为虚构测试数据。\n## 一、适用范围与安全原则\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\n## 二、通用排查流程\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\n## 三、E-17 时钟偏差故障\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\n## 四、E-42 事件队列积压\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\n## 五、R-09 机器人安全联锁异常\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\n## 六、S-03 温度传感器校准偏移\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\n## 七、N-11 工业网络丢包\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\n## 八、G-08 规则包不一致\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\n## 九、升级、交接与关闭\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。', '353285809898651649', '{\"skipEmbedding\":1,\"fileName\":\"04_曙光智造园区故障排查指南\",\"headerLevel\":1,\"docId\":4,\"title\":\"曙光智造园区故障排查指南\",\"chunkId\":\"353285809898651649\",\"version\":4,\"url\":\"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\"}', 4, 4, 0, NULL, 'STORED', 1, '2026-09-01 21:11:41', '2026-09-01 21:11:41', 0, 0);
INSERT INTO `knowledge_segment` VALUES (34, '# 曙光智造园区故障排查指南\n文档版本：2.5\n生效日期：2026年8月28日\n本文中的名称、编号、阈值和案例均为虚构测试数据。\n## 一、适用范围与安全原则\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\n## 二、通用排查流程\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\n## 三、E-17 时钟偏差故障\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因', '353285809898651650', '{\"fileName\":\"04_曙光智造园区故障排查指南\",\"headerLevel\":1,\"docId\":4,\"title\":\"曙光智造园区故障排查指南\",\"chunkId\":\"353285809898651650\",\"version\":4,\"url\":\"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\",\"parentChunkId\":\"353285809898651649\"}', 4, 4, 1, '2c2b36bf-4e9e-4b5b-8792-68c92ac2c047', 'VECTOR_STORED', 0, '2026-09-01 21:11:41', '2026-09-01 21:11:41', 1, 0);
INSERT INTO `knowledge_segment` VALUES (35, '三、E-17 时钟偏差故障\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\n## 四、E-42 事件队列积压\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费', '353285809898651651', '{\"fileName\":\"04_曙光智造园区故障排查指南\",\"headerLevel\":1,\"docId\":4,\"title\":\"曙光智造园区故障排查指南\",\"chunkId\":\"353285809898651651\",\"version\":4,\"url\":\"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\",\"parentChunkId\":\"353285809898651649\"}', 4, 4, 2, 'cab789af-1f0a-48d8-82dc-952b25dcecac', 'VECTOR_STORED', 0, '2026-09-01 21:11:41', '2026-09-01 21:11:41', 1, 0);
INSERT INTO `knowledge_segment` VALUES (36, '低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\n## 五、R-09 机器人安全联锁异常\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\n## 六、S-03 温度传感器校准偏移\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\n## 七、N-11 工业网络丢包\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\n处置步骤：检查接口错', '353285809898651652', '{\"fileName\":\"04_曙光智造园区故障排查指南\",\"headerLevel\":1,\"docId\":4,\"title\":\"曙光智造园区故障排查指南\",\"chunkId\":\"353285809898651652\",\"version\":4,\"url\":\"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\",\"parentChunkId\":\"353285809898651649\"}', 4, 4, 3, '8d154015-724f-4bcd-a82a-a9fe4a5fb987', 'VECTOR_STORED', 0, '2026-09-01 21:11:41', '2026-09-01 21:11:41', 1, 0);
INSERT INTO `knowledge_segment` VALUES (37, '通知设施保障组更换传感器。\n## 七、N-11 工业网络丢包\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\n## 八、G-08 规则包不一致\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\n## 九、升级、交接与关闭\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。', '353285809898651653', '{\"fileName\":\"04_曙光智造园区故障排查指南\",\"headerLevel\":1,\"docId\":4,\"title\":\"曙光智造园区故障排查指南\",\"chunkId\":\"353285809898651653\",\"version\":4,\"url\":\"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\",\"parentChunkId\":\"353285809898651649\"}', 4, 4, 4, '81f01533-6dc0-4df1-9321-061d0e50e87e', 'VECTOR_STORED', 0, '2026-09-01 21:11:41', '2026-09-01 21:11:41', 1, 0);
INSERT INTO `knowledge_segment` VALUES (38, '资产编号：AU-GW-001; 资产名称：北区边缘网关; 生产区：A区; 子区域：A1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-18; 下次维护时间：2026-09-02 02:00; 维护任务：固件校验; 维护时长（分钟）：45; 关键等级：关键; 备注：负责A区采集', '353285847806771200', '{\"fileName\":\"05_曙光智造园区资产与维护清单\",\"chunkId\":\"353285847806771200\",\"version\":5,\"docId\":5,\"url\":\"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\"}', 5, 5, 0, '9eab4023-a391-4a26-8682-be6239994fc7', 'VECTOR_STORED', 0, '2026-09-01 21:11:50', '2026-09-01 21:11:50', 1, 0);
