INSERT INTO `knowledge_segment` VALUES (40, '资产编号：AU-GW-003; 资产名称：装配区边缘网关; 生产区：C区; 子区域：C1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-20; 下次维护时间：2026-09-16 02:00; 维护任务：时钟校验; 维护时长（分钟）：30; 关键等级：关键; 备注：负责C区采集', '353285847806771202', '{\"fileName\":\"05_曙光智造园区资产与维护清单\",\"chunkId\":\"353285847806771202\",\"version\":5,\"docId\":5,\"url\":\"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\"}', 5, 5, 2, 'c9d6ad4e-5d07-43c6-a507-ed30b8a99441', 'VECTOR_STORED', 0, '2026-09-01 21:11:50', '2026-09-01 21:11:50', 1, 0);
INSERT INTO `knowledge_segment` VALUES (41, '资产编号：AU-SN-014; 资产名称：十四号温度传感器; 生产区：B区; 子区域：B2; 设备型号：TS-9; 责任团队：设施保障组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-02 02:50; 维护任务：温度校准; 维护时长（分钟）：20; 关键等级：重要; 备注：环境关键测点', '353285847806771203', '{\"fileName\":\"05_曙光智造园区资产与维护清单\",\"chunkId\":\"353285847806771203\",\"version\":5,\"docId\":5,\"url\":\"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\"}', 5, 5, 3, '29dcb727-2ff6-44ed-b719-c678e1fa1eba', 'VECTOR_STORED', 0, '2026-09-01 21:11:50', '2026-09-01 21:11:50', 1, 0);
